b('Ex 5.7 Q8: y = tan⁻¹x.', 'y′ = 1/(1 + x²); ' + N('y″ = −2x/(1 + x²)²'))
b('Ex 5.7 Q9: y = log(log x).', 'y′ = 1/(x log x); ' + N('y″ = −(1 + log x)/(x log x)²'))
b('Ex 5.7 Q10: y = sin(log x).', 'y′ = cos(log x)/x; ' + N('y″ = −[sin(log x) + cos(log x)]/x²'))
