b('Ex 5.7 Q15: y = 500e^(7x) + 600e^(−7x). Show y″ = 49y.', 'y″ = 49·500e^(7x) + 49·600e^(−7x) = 49y. ' + E('✓'))
b('Ex 5.7 Q16: eʸ(x + 1) = 1. Show y″ = (y′)².', 'y = −log(x + 1), y′ = −1/(x + 1), y″ = 1/(x + 1)² = (y′)². ' + E('✓'))
